const items = $input.all();

function safeText(v) {
  return (v == null ? '' : String(v)).trim();
}

function getTitle(j) {
  if (j.property_task_name) return safeText(j.property_task_name);
  if (j.name) return safeText(j.name);
  const p = j.properties || {};
  const prop = p['Task name'] || p['Name'] || p['Title'];
  if (prop?.title?.length) {
    return prop.title.map(t => t.plain_text || t.text?.content || '').join('').trim();
  }
  return '';
}

function getStatus(j) {
  if (j.property_status) return safeText(j.property_status);
  const s = j.properties?.['Status']?.status?.name;
  return s ? safeText(s) : 'Not started';
}

function getDueDate(j) {
  const d = j.property_due_date;
  if (d?.start) return String(d.start).slice(0, 10);
  if (typeof d === 'string' && d) return d.slice(0, 10);
  const p = j.properties || {};
  const due = p['Due date']?.date?.start || p['Due']?.date?.start || null;
  return due ? String(due).slice(0, 10) : null;
}

function getGoogleTaskId(j) {
  if (j.property_google_task_id) return safeText(j.property_google_task_id);
  const p = j.properties || {};
  return safeText(
    p['Google Task ID']?.rich_text?.[0]?.plain_text ||
    p['Google Tasks ID']?.rich_text?.[0]?.plain_text ||
    ''
  );
}

function getGoogleTasklistId(j) {
  if (j.property_google_tasklist_id) return safeText(j.property_google_tasklist_id);
  const p = j.properties || {};
  return safeText(p['Google Tasklist ID']?.rich_text?.[0]?.plain_text || '');
}

function getNotes(j) {
  if (j.property_notes != null) return String(j.property_notes || '').slice(0, 8192);
  const p = j.properties || {};
  return String(p['Notes']?.rich_text?.[0]?.plain_text || '').slice(0, 8192);
}

function normDate(d) {
  return d ? String(d).slice(0, 10) : null;
}

return items.map(item => {
  const j = item.json;
  const title = getTitle(j) || '(Untitled)';
  const googleTaskId = getGoogleTaskId(j);
  const googleTasklistId = getGoogleTasklistId(j);
  const notionStatus = getStatus(j);
  const dueDate = normDate(getDueDate(j));

  return {
    json: {
      notionPageId: j.id,
      title,
      notionStatus,
      dueDate,
      notes: getNotes(j),
      googleTaskId,
      googleTasklistId,
      hasGoogleLink: !!googleTaskId
    }
  };
});

const notionItems = $('Prepare Notion Tasks').all().map(i => i.json);
const googleItems = $('Get Google Tasks (Notion branch)').all().map(i => i.json);

const NOW = Date.now();
const DAYS_14_MS = 14 * 24 * 60 * 60 * 1000;
const TASKLIST_ID = 'MDk4NTUxODgzNzA1NDM2OTIxNjg6MDow';

function normDate(d) {
  return d ? String(d).slice(0, 10) : null;
}

function inScopeGoogleTask(g) {
  if (g.status !== 'completed') return true;
  const updated = g.updated ? new Date(g.updated).getTime() : 0;
  return updated && (NOW - updated <= DAYS_14_MS);
}

const googleById = new Map();
for (const g of googleItems) {
  if (!inScopeGoogleTask(g)) continue;
  googleById.set(String(g.id), g);
}

const out = [];

for (const n of notionItems) {
  const gid = (n.googleTaskId || '').trim();

  if (!gid) {
    out.push({
      json: {
        action: 'create_google',
        reason: 'no_google_task_id',
        notionPageId: n.notionPageId,
        title: n.title || '(Untitled)',
        notionStatus: n.notionStatus || 'Not started',
        dueDate: normDate(n.dueDate),
        notes: n.notes || '',
        googleTaskId: '',
        googleTasklistId: TASKLIST_ID,
        needsWriteBack: true,
      },
    });
    continue;
  }

  const g = googleById.get(gid);
  if (!g) {
    out.push({
      json: {
        action: 'skip_missing_linked',
        reason: 'google_task_not_found_in_index',
        notionPageId: n.notionPageId,
        title: n.title || '(Untitled)',
        googleTaskId: gid,
        googleTasklistId: n.googleTasklistId || TASKLIST_ID,
        needsWriteBack: false,
      },
    });
    continue;
  }

  out.push({
    json: {
      action: 'skip_no_change',
      reason: 'linked_task_managed_by_google',
      notionPageId: n.notionPageId,
      title: n.title || '(Untitled)',
      googleTaskId: gid,
      googleTasklistId: n.googleTasklistId || TASKLIST_ID,
      needsWriteBack: false,
    },
  });
}

return out;

