const notionPages = $('Get All Notion Pages').all().map(i => i.json);

const TASKLIST_ID = 'MDk4NTUxODgzNzA1NDM2OTIxNjg6MDow';

function safeText(v) {
  return (v == null ? '' : String(v)).trim();
}

function notionTitle(j) {
