}

function notionDue(j) {
  const d = j.property_due_date;
  if (d?.start) return String(d.start).slice(0, 10);
  if (typeof d === 'string' && d) return d.slice(0, 10);
  return null;
}

function notionGoogleTaskId(j) {
  return safeText(j.property_google_task_id || '');
}

function notionGoogleTasklistId(j) {
  return safeText(j.property_google_tasklist_id || '');
}

function statusToNotion(googleStatus) {
  return googleStatus === 'completed' ? 'Done' : 'Not started';
}

function normDate(d) {
  return d ? String(d).slice(0, 10) : null;
}

const notionByGid = new Map();
for (const p of notionPages) {
  const gid = notionGoogleTaskId(p);
  if (!gid) continue;
  const existing = notionByGid.get(gid);
  if (!existing) {
    notionByGid.set(gid, p);
  } else {
    const a = new Date(existing.updatedAt || 0).getTime();
    const b = new Date(p.updatedAt || 0).getTime();
    if (b >= a) notionByGid.set(gid, p);
  }
}

const out = [];

for (const g of googleItems) {
  const gid = safeText(g.googleTaskId);
  const matched = notionByGid.get(gid);

  if (!matched) {
    out.push({
      json: {
        action: 'create_notion',
        notionPageId: null,
        googleTaskId: gid,
        googleTasklistId: g.googleTasklistId || TASKLIST_ID,
        title: g.title || '(Untitled)',
        googleStatus: g.googleStatus || 'needsAction',
        dueDate: normDate(g.dueDate),
        webViewLink: g.webViewLink || ''
      }
    });
    continue;
  }

  const targetTitle = g.title || '(Untitled)';
  const targetStatus = statusToNotion(g.googleStatus);
  const targetDue = normDate(g.dueDate);
  const targetTasklist = g.googleTasklistId || TASKLIST_ID;
  const currentTitle = notionTitle(matched);
  const currentStatus = notionStatus(matched);
  const currentDue = normDate(notionDue(matched));
  const currentTasklist = notionGoogleTasklistId(matched);
  const currentUrl = safeText(matched.property_google_task_url || '');

  const changed =
    currentTitle !== targetTitle ||
    currentStatus !== targetStatus ||
    currentDue !== targetDue ||
    currentTasklist !== targetTasklist ||
    currentUrl !== (g.webViewLink || '');

  if (changed) {
    out.push({
      json: {
        action: 'update_notion',
        notionPageId: matched.id,
        googleTaskId: gid,
        googleTasklistId: targetTasklist,
        title: targetTitle,
        googleStatus: g.googleStatus || 'needsAction',
        dueDate: targetDue,
        webViewLink: g.webViewLink || ''
      }
    });
  }
}

return out;

const scanned = $('Prepare Notion Tasks').all().length;
const plannedItems = $('Plan Notion->Google Actions').all();

let created = 0;
let updated = 0;
let skippedNoChange = 0;
let missingLinked = 0;
let errors = 0;

const missingLinkedIds = [];

for (const item of plannedItems) {
  const p = item.json || {};

  if (p.action === 'create_google') {
    created += 1;
    if (!p.notionPageId) errors += 1;
  } else if (p.action === 'update_google_notes') {
    updated += 1;
    if (!p.googleTaskId) errors += 1;
  } else if (p.action === 'skip_missing_linked') {
    missingLinked += 1;
    if (p.googleTaskId && missingLinkedIds.length < 20) {
      missingLinkedIds.push(p.googleTaskId);
    }
  } else if (p.action === 'skip_no_change') {
    skippedNoChange += 1;
  }
}

const actionable = created + updated;
const skipped = Math.max(0, scanned - actionable);

return [{
  json: {
    branch: 'notion_to_google',
    scanned,
    created,
    updated,
    skipped,
    skippedNoChange,
    missing_linked: missingLinked,
    missing_linked_ids: missingLinkedIds,
    errors,
    timestamp: new Date().toISOString(),
  },
}];

